import SwiftUI
import UniformTypeIdentifiers
final class CommunityRedirectGuard:NSObject,URLSessionTaskDelegate {
 func urlSession(_ session:URLSession,task:URLSessionTask,willPerformHTTPRedirection response:HTTPURLResponse,newRequest request:URLRequest,completionHandler:@escaping(URLRequest?)->Void){completionHandler(nil)}
}
@MainActor final class CommunityStore:ObservableObject {
 @Published var dataset:CommunityDataset?
 @Published var message="아직 자료가 없습니다. 새로고침 또는 파일 가져오기를 선택하세요."
 @Published var busy=false
 var task:Task<Void,Never>?,generation=0,lastFetch:TimeInterval = -60
 func cancel(){generation+=1;task?.cancel();task=nil;busy=false}
 func fetch(){guard !busy else{return};let now=ProcessInfo.processInfo.systemUptime;guard now-lastFetch>=60 else{message="공개 목록 새로고침은 60초 간격입니다.";return};lastFetch=now;cancel();busy=true;let token=generation;message="공개 목록 읽는 중 · 기존 표시는 이전 수집 자료입니다."
 task=Task{do{let config=URLSessionConfiguration.ephemeral;config.timeoutIntervalForRequest=20;config.timeoutIntervalForResource=20;config.httpShouldSetCookies=false;let session=URLSession(configuration:config,delegate:CommunityRedirectGuard(),delegateQueue:nil);defer{session.invalidateAndCancel()};var request=URLRequest(url:URL(string:CommunityCore.dcList)!);request.setValue("CryptoResearch/1.8 (public-title-reader)",forHTTPHeaderField:"User-Agent");let (bytes,response)=try await session.bytes(for:request);guard let http=response as? HTTPURLResponse,http.statusCode==200,http.mimeType=="text/html"else{throw StrategyError.invalid("접근 제한 또는 응답 오류")};var data=Data();for try await byte in bytes{try Task.checkCancellation();guard data.count<2097152 else{throw StrategyError.invalid("응답 2MB 초과")};data.append(byte)};guard let html=String(data:data,encoding:.utf8)else{throw StrategyError.invalid("UTF-8 응답 필요")};let at=Int64(Date().timeIntervalSince1970*1000);let d=try await Task.detached(priority:.userInitiated){try CommunityCore.dcHTML(html,at)}.value;guard token==generation,!Task.isCancelled else{return};dataset=d;message="수신 완료 · 제목 기반 참고 통계";busy=false}catch{guard token==generation,!Task.isCancelled else{return};busy=false;message="자동 조회 불가 · \(error.localizedDescription) · 기존 자료는 수집 시각을 확인하세요."}}
 }
 func load(_ url:URL){cancel();busy=true;let token=generation;task=Task{do{let d=try await Task.detached(priority:.userInitiated){let access=url.startAccessingSecurityScopedResource();defer{if access{url.stopAccessingSecurityScopedResource()}};let handle=try FileHandle(forReadingFrom:url);defer{try? handle.close()};let data=try handle.read(upToCount:1048577) ?? Data();return try CommunityCore.parse(data,Int64(Date().timeIntervalSince1970*1000))}.value;guard token==generation,!Task.isCancelled else{return};dataset=d;busy=false;message="파일 수신 · 출처는 검증되지 않았습니다."}catch{guard token==generation,!Task.isCancelled else{return};busy=false;message="파일 분석 실패 · \(error.localizedDescription)"}}}
}
struct CommunityView:View {
 @StateObject private var store=CommunityStore()
 @State private var symbol="전체"
 @State private var hours:Int64=24
 @State private var importing=false
 @State private var exporting=false
 @State private var document=JSONDocument(data:Data())
 @Environment(\.openURL) private var openURL
 var analysis:CommunityAnalysis?{store.dataset.map{CommunityCore.analyze($0,symbol,hours,Int64(Date().timeIntervalSince1970*1000))}}
 var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){controls;if let a=analysis{Text(CommunityCore.summary(a)).font(.system(.caption,design:.monospaced)).textSelection(.enabled).modifier(CareCard());if a.posts.isEmpty{Text("해당 기간·종목의 분석 표본이 없습니다.").modifier(CareCard())};ForEach(Array(a.posts.prefix(20).enumerated()),id:\.offset){item in postCard(item.element)}}}.padding(20)}.background(Color(uiColor:.systemGroupedBackground)).navigationTitle("국내 커뮤니티 분석").onDisappear{store.cancel()}.fileImporter(isPresented:$importing,allowedContentTypes:[.json],allowsMultipleSelection:false){result in switch result{case .success(let urls):if let url=urls.first{store.load(url)};case .failure(let error):store.message=error.localizedDescription}}.fileExporter(isPresented:$exporting,document:document,contentType:.json,defaultFilename:"community-title-analysis"){result in if case .failure(let error)=result{store.message=error.localizedDescription}}}
 var controls:some View{VStack(alignment:.leading,spacing:14){Text("제목에서 종목 언급과 표현을 살펴봐요").font(.title3.bold());Text("디시 최신 목록1페이지 · 코인판 JSON 가져오기\n댓글·작성자·계정은 수집하지 않습니다. 자동 주문 신호로 사용하지 않습니다.").font(.caption).foregroundStyle(.secondary);Picker("커뮤니티 종목 필터",selection:$symbol){ForEach(CommunityCore.symbols,id:\.self){Text($0).tag($0)}};Picker("분석 기간",selection:$hours){Text("최근24시간").tag(Int64(24));Text("최근7일").tag(Int64(168))}.pickerStyle(.segmented);Button("디시 공개 목록 새로고침"){store.fetch()}.disabled(store.busy).frame(minHeight:44);Button("커뮤니티 JSON 가져오기"){importing=true}.disabled(store.busy).frame(minHeight:44);Button("합성 예제로 분석 확인"){store.dataset=CommunityCore.sample(Int64(Date().timeIntervalSince1970*1000));store.message="합성 예제 · 실제 커뮤니티 자료 아님"}.disabled(store.busy).frame(minHeight:44);Button("집계 JSON 내보내기"){guard let a=analysis else{return};do{document=JSONDocument(data:try CommunityCore.report(a));exporting=true}catch{store.message=error.localizedDescription}}.disabled(store.dataset==nil).frame(minHeight:44);Link("코인판 원문 열기",destination:URL(string:"https://coinpan.com/free")!).frame(minHeight:44);Link("디시 원문 열기",destination:URL(string:CommunityCore.dcList)!).frame(minHeight:44);if store.busy{ProgressView()};Text(store.message).font(.caption).foregroundStyle(.secondary)}.modifier(CareCard())}
 func postCard(_ post:CommunityPost)->some View{VStack(alignment:.leading,spacing:10){Text(post.title).font(.headline);Text(post.source+" · "+Date(timeIntervalSince1970:Double(post.published_ms)/1000).formatted(date:.numeric,time:.standard)).font(.caption).foregroundStyle(.secondary);if !post.url.isEmpty,CommunityCore.safeURL(post.source,post.url),let url=URL(string:post.url){Button("이 게시글 원문 열기"){openURL(url)}.frame(minHeight:44)}}.modifier(CareCard())}
}
